@namespace sv_02bac541e9fe40f2927636b6deca58ab.Components.Pages.Apply

<div>
    <h4 class="mb-3">References</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Refs.Count; i++)
    {
        var index = i;
        var r = Refs[index];
        <ReferenceForm Index="index"
                       Name="@r.Name"
                       Relationship="@r.Relationship"
                       Email="@r.Email"
                       Phone="@r.Phone"
                       CanRemove="@(Refs.Count > 2)"
                       OnChanged="data => UpdateRef(index, data)"
                       OnRemove="() => RemoveRef(index)" />
    }

    @if (Refs.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddRef">
            <span class="me-1">+</span> Add Reference
        </button>
    }

    <div class="d-flex justify-content-between mt-3">
        <button class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
