@page "/apply"
@using sv_02bac541e9fe40f2927636b6deca58ab.Models
@using sv_02bac541e9fe40f2927636b6deca58ab.Services
@namespace sv_02bac541e9fe40f2927636b6deca58ab.Components.Pages.Apply

@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep" CompletedUpTo="completedUpTo" OnNavigate="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalInfo.FullName"
                              Email="@personalInfo.Email"
                              Phone="@personalInfo.Phone"
                              Address="@personalInfo.Address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="workEntries" OnNext="HandleWorkNext" OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep Refs="references" OnNext="HandleRefsNext" OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter" OnNext="HandleCoverNext" OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep Personal="@(new PersonalInfoStep.PersonalInfoResult(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address))"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="@coverLetter"
                        OnBack="GoBack"
                        OnEdit="GoToStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private int completedUpTo;

    // State for each step
    private (string FullName, string Email, string Phone, string Address) personalInfo = ("", "", "", "");
    private List<WorkHistoryStep.WorkEntryData> workEntries = new() { new() };
    private List<ReferencesStep.ReferenceData> references = new() { new(), new() };
    private string coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        if (step <= completedUpTo)
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0) currentStep--;
    }

    private void Advance()
    {
        currentStep++;
        if (completedUpTo < currentStep)
            completedUpTo = currentStep;
    }

    private void HandlePersonalNext(PersonalInfoStep.PersonalInfoResult result)
    {
        personalInfo = (result.FullName, result.Email, result.Phone, result.Address);
        Advance();
    }

    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryData> entries)
    {
        workEntries = entries;
        Advance();
    }

    private void HandleRefsNext(List<ReferencesStep.ReferenceData> refs)
    {
        references = refs;
        Advance();
    }

    private void HandleCoverNext(string letter)
    {
        coverLetter = letter;
        Advance();
    }

    private async Task<int> SubmitApplication()
    {
        var personal = new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address);

        var workHistory = new WorkHistory(workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description)
        ).ToList());

        var refs = references.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)
        ).ToList();

        var application = new JobApplication(personal, workHistory, refs, coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

